import assert from 'node:assert/strict';import {randomUUID} from 'node:crypto';
import {lanes as nine} from './maintenance-nine-lanes.mjs';import {identity} from './model-settings.mjs';
export const lanes={...nine,sourceCacheCleanup:{key:'source_cache_cleanup',begin:()=>({action:'prepare',...identity,document:'22222222-2222-4222-8222-222222222222',invocation:randomUUID()})}};
export async function verifyNinetyDirections(request){let pairs=0,old72=0;for(const [old,a]of Object.entries(lanes))for(const [newer,b]of Object.entries(lanes)){if(old===newer)continue;const ready=(await request(old,a.begin()))[a.key];assert.ok(old==='inspectSourceCache'?ready.status==='reported':ready.reference,old);const next=(await request(newer,b.begin()))[b.key];assert.ok(newer==='inspectSourceCache'?next.status==='reported':next.reference,newer);if(old!=='inspectSourceCache'){const q=a.change?{action:'save',...identity,reference:ready.reference,change:a.change}:a.changes?{action:'save',...identity,reference:ready.reference,changes:a.changes}:old==='memoryForget'?{action:'confirm',reference:ready.reference}:old==='sourceCacheCleanup'?{action:'confirm',...identity,reference:ready.reference,invocation:randomUUID()}:{action:'confirm',...identity,reference:ready.reference};const v=(await request(old,q))[a.key];assert.ok(['invalidated','unavailable','not-dispatched'].includes(v.state),`${old} after ${newer}: ${v.state}`);}if(old!=='sourceCacheCleanup'&&newer!=='sourceCacheCleanup')old72++;pairs++;}assert.equal(pairs,90);assert.equal(old72,72);}
export async function verifyNinetyBusyDirections(request,control){let pairs=0;for(const [old,a]of Object.entries(lanes)){await control.hold();const pending=request(old,a.begin());await control.entered();try{const before=await control.snapshot();for(const [newer,b]of Object.entries(lanes)){if(old===newer)continue;const v=(await request(newer,b.begin()))[b.key];assert.equal(newer==='inspectSourceCache'?v.status:v.state,'busy',`${old} holds, ${newer} refused`);assert.deepEqual(await control.snapshot(),before,'Busy has no hook/cancel/raw side effect');pairs++;}}finally{await control.release();}await pending;}assert.equal(pairs,90);}
